function validate([edges, colors]) {
  const n = colors.length;
  if (n < 1 || n > 50000) return 'colors needs 1 to 50000 values.';
  if (edges.length !== n - 1) return 'edges must have exactly colors.length - 1 pairs.';
  if (colors.some(c => !Number.isInteger(c) || c < 1 || c > 100000)) return 'Each color is an integer from 1 to 100000.';
  const root = Array.from({ length: n }, (_, i) => i);
  const find = x => { while (root[x] !== x) { root[x] = root[root[x]]; x = root[x]; } return x; };
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2) return 'Each edge is a pair [u, v].';
    const [u, v] = edge;
    if (!Number.isInteger(u) || !Number.isInteger(v) || u < 0 || v < 0 || u >= n || v >= n) return 'Edge endpoints must be node labels from 0 to n - 1.';
    const a = find(u), b = find(v);
    if (a === b) return 'edges must form a tree (no cycles or repeated edges).';
    root[a] = b;
  }
  return null;
}

