function maximumSubtreeSize(edges, colors) {
  const n = colors.length;
  const graph = Array.from({ length: n }, () => []);
  for (const [u, v] of edges) {
    graph[u].push(v);
    graph[v].push(u);
  }
  const parent = new Array(n).fill(-1);
  const order = [0];
  for (let i = 0; i < order.length; i++) {
    const node = order[i];
    for (const next of graph[node]) {
      if (next !== parent[node]) {
        parent[next] = node;
        order.push(next);
      }
    }
  }
  const size = new Array(n).fill(1);
  const same = new Array(n).fill(true);
  let best = 0;
  for (let i = n - 1; i >= 0; i--) {
    const node = order[i];
    if (same[node]) {
      best = Math.max(best, size[node]);
    }
    const up = parent[node];
    if (up === -1) {
      continue;
    }
    size[up] += size[node];
    if (!same[node] || colors[node] !== colors[up]) {
      same[up] = false;
    }
  }
  return best;
}

