function maximumSubtreeSize(edges, colors) {
  const n = colors.length;
  const adj = [];
  for (let i = 0; i < n; i++) adj.push([]);
  edges.forEach(([a, b]) => { adj[a].push(b); adj[b].push(a); });
  const par = Array(n).fill(null);
  const visit = (x, p) => { par[x] = p; for (const y of adj[x]) if (y !== p) visit(y, x); };
  visit(0, -1);
  const isBelow = (u, v) => { for (let x = u; x !== -1; x = par[x]) if (x === v) return true; return false; };
  let answer = 0;
  for (let v = 0; v < n; v++) {
    const members = [];
    for (let u = 0; u < n; u++) if (isBelow(u, v)) members.push(u);
    if (members.every(u => colors[u] === colors[v])) answer = Math.max(answer, members.length);
  }
  return answer;
}

