function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 10);
  const label = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [label[i], label[j]] = [label[j], label[i]]; }
  // Shape: 0 = random, 1 = path-like, 2 = star-like.
  const shape = Math.floor(rand() * 3);
  const edges = [];
  for (let i = 1; i < n; i++) {
    let p;
    if (shape === 1) p = Math.max(0, i - 1 - Math.floor(rand() * 2));
    else if (shape === 2) p = Math.floor(rand() * Math.min(i, 3));
    else p = Math.floor(rand() * i);
    edges.push(rand() < 0.5 ? [label[i], label[p]] : [label[p], label[i]]);
  }
  for (let i = edges.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [edges[i], edges[j]] = [edges[j], edges[i]]; }
  let colors;
  if (size === 'large') {
    const rare = 0.002 + rand() * 0.02;
    const base = 1 + Math.floor(rand() * 100000);
    colors = Array.from({ length: n }, () => rand() < rare ? 1 + Math.floor(rand() * 100000) : base);
  } else {
    const palette = 1 + Math.floor(rand() * 3);
    colors = Array.from({ length: n }, () => 1 + Math.floor(rand() * palette));
  }
  return [edges, colors];
}
